/* The Rust commands and events, typed. `bindings.ts` is generated by tauri-specta from
   app/src-tauri/src/main.rs and ipc.rs (a debug start-up rewrites it when it changed, a Rust test
   checks the committed file), so a command a page calls, its arguments and what it returns are
   the Rust side's own. Call them as `commands.overview()`, listen as `events.meters.listen(...)`.
   In a plain browser during development (`bun run dev`, no Tauri) lib/mock.ts answers the same
   commands and sends the same events through Tauri's own IPC mock; a production build never
   contains it. */

import type { Settings_Serialize } from "./bindings";

export { commands, events } from "./bindings";

/* What the window receives, by its plain name. Specta writes a `_Serialize` shape (what Rust
   sends: every field present) and a `_Deserialize` one (what Rust accepts: defaults may be left
   out) wherever the two differ (ZER0 names them the same way). */
export type {
  AboutInfo_Serialize as AboutInfo,
  Build,
  ConvertDone_Serialize as ConvertDone,
  EngineAction,
  EngineCheck_Serialize as EngineCheck,
  EngineDone_Serialize as EngineDone,
  EngineStatus_Serialize as EngineStatus,
  Gpu,
  InputInfo_Serialize as InputInfo,
  Meters_Serialize as Meters,
  ModelDone_Serialize as ModelDone,
  ModelProgress,
  ModelStatus_Serialize as ModelStatus,
  Overview_Serialize as Overview,
  ServerCommand,
  ServerLog_Serialize as ServerLog,
} from "./bindings";

export const inTauri = typeof window !== "undefined" && "__TAURI_INTERNALS__" in window;

/** The settings file (docs/settings.md), as `settings_get` returns it: every section, every key. */
export type Settings = Settings_Serialize;
export type Section = keyof Settings;

/** One line of the conversion's progress (`sift-event`): the JSON the command line prints with
 * `--json`, documented in docs/events.md. Rust sends it as JSON (`ConvertEvent`); its fields
 * depend on `type`, so it is typed here rather than in Rust. */
export type SiftEvent = {
  type: string;
  t?: number;
  file?: string;
  name?: string;
  done?: number;
  total?: number;
  index?: number;
  pages?: number;
  files?: number;
  output?: string;
  mode?: string;
  describer?: string;
  engine?: string | null;
  skipped?: number;
  message?: string;
  md?: string | null;
  images?: number;
  report?: string | null;
  seconds?: number;
  stats?: Record<string, number>;
  model?: string;
  state?: string;
  error?: string;
  /** file_error: the file stopped on Cancel, nothing was written for it */
  cancelled?: boolean;
  ok?: number;
  failed?: number;
};
